use std::fs::File;
use std::io::{self, Read};

/// Reads the packet header from an open file and returns the packet ID
/// parsed from the first two bytes.
pub fn vtx_read_packet_id(file: &File) -> Result<u16, io::Error> {
    let mut buffer = [0u8; 4096];
    let mut filled = 0usize;

    while filled < 2 {
        match file.read(&mut buffer[filled..])? {
            0 => break,
            n => filled += n,
        }
    }

    if filled < 2 {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            "packet header truncated",
        ));
    }

    Ok(u16::from_be_bytes([buffer[0], buffer[1]]))
}

