use std::io::{Error, ErrorKind, Read};

/// Reads from `file` into the standard 4096-byte buffer and returns the
/// packet ID encoded in the first two bytes (big-endian).
pub fn vtx_read_packet_id(file: &mut File) -> Result<u16, Error> {
    const BUFFER_SIZE: usize = 4096;

    let mut buffer = [0u8; BUFFER_SIZE];
    let mut filled = 0usize;

    while filled < 2 {
        let n = file.read(&mut buffer[filled..])?;
        if n == 0 {
            return Err(Error::new(
                ErrorKind::UnexpectedEof,
                "packet shorter than two bytes",
            ));
        }
        filled += n;
    }

    Ok(u16::from_be_bytes([buffer[0], buffer[1]]))
}

